/* my_element — "Highlight Box" front-end styles. */

.my-element {
	border: 1px solid #d7dbe0;
	border-left: 4px solid #00b295; /* Unyson+ green accent */
	border-radius: 8px;
	padding: 16px 20px;
	background: #f7faf9;
}

.my-element--center { text-align: center; }
.my-element--right  { text-align: right; }

.my-element__heading {
	margin: 0 0 6px;
	font-size: 1.05rem;
	line-height: 1.3;
}

.my-element__text {
	margin: 0;
	color: #5f6266;
}

/* Scroll-reveal — the --reveal class is added by my_element.js, so with no JS
   (or reduced-motion) the box simply stays visible. */
.my-element--reveal {
	opacity: 0;
	transform: translateY(8px);
	transition: opacity 0.4s ease, transform 0.4s ease;
}

.my-element--reveal.is-visible {
	opacity: 1;
	transform: none;
}

/* my_element — reveal each Highlight Box as it scrolls into view.
 *
 * Progressive enhancement: the box is fully visible with no JS. This script
 * adds the hidden start state itself (the `--reveal` class), so if the script
 * never loads, nothing is hidden. It also bows out when the visitor prefers
 * reduced motion.
 */
(function () {
	var boxes = document.querySelectorAll('.my-element');
	if (!boxes.length) return;

	var reduce =
		window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
	if (reduce || !('IntersectionObserver' in window)) return;

	var io = new IntersectionObserver(
		function (entries) {
			entries.forEach(function (entry) {
				if (entry.isIntersecting) {
					entry.target.classList.add('is-visible');
					io.unobserve(entry.target);
				}
			});
		},
		{ threshold: 0.15 }
	);

	boxes.forEach(function (box) {
		box.classList.add('my-element--reveal'); // hidden start state, added only when JS runs
		io.observe(box);
	});
})();
